import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import LinkButton from 'flarum/common/components/LinkButton';
import UserPage from 'flarum/forum/components/UserPage';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import CommentPost from 'flarum/forum/components/CommentPost';
import { registerModels } from '../common/models';
import EmbedCard from './components/EmbedCard';
import { t } from './util';
import { loadStyles } from './styles';

/*
 * forum.js is loaded on every page, so it only wires things up: the routes,
 * the sidebar link, the profile tab, the notifications, a build's card in
 * posts and under signatures. The pages and the forms are chunks fetched when
 * opened.
 */

app.initializers.add('ernestdefoe-garage', () => {
  registerModels(app);

  // Each page and the shared styles load side by side.
  const page = load => () => Promise.all([load(), loadStyles()]).then(([module]) => module);
  app.routes['garage'] = {
    path: '/garage',
    component: page(() => import(/* webpackChunkName: 'forum/components/GaragePage', webpackMode: 'lazy-once' */ './components/GaragePage'))
  };
  app.routes['garage.build'] = {
    path: '/garage/:id',
    component: page(() => import(/* webpackChunkName: 'forum/components/BuildPage', webpackMode: 'lazy-once' */ './components/BuildPage'))
  };
  app.routes['user.garage'] = {
    path: '/u/:username/garage',
    component: page(() => import(/* webpackChunkName: 'forum/components/UserGaragePage', webpackMode: 'lazy-once' */ './components/UserGaragePage'))
  };
  extend(IndexSidebar.prototype, 'navItems', function (items) {
    if (!app.forum.attribute('garageCanView') || !app.forum.attribute('garageNav')) return;
    items.add('garage', m(LinkButton, {
      href: app.route('garage'),
      icon: "fas fa-warehouse"
    }, t('nav')), 84);
  });
  extend(UserPage.prototype, 'navItems', function (items) {
    if (!this.user || !app.forum.attribute('garageCanView')) return;
    const count = this.user.attribute('garageBuildCount') || 0;
    // A member with no builds gets no tab, except on their own profile (where they add one).
    if (!count && app.session.user !== this.user) return;
    items.add('garage', m(LinkButton, {
      href: app.route('user.garage', {
        username: this.user.slug()
      }),
      icon: "fas fa-warehouse"
    }, t('profile.nav'), " ", m("span", {
      className: "Button-badge"
    }, count)), 85);
  });
  extend('flarum/forum/components/NotificationGrid', 'notificationTypes', items => {
    items.add('garageNewEntry', {
      name: 'garageNewEntry',
      icon: 'fas fa-screwdriver-wrench',
      label: t('notifications.new_entry_setting')
    });
    items.add('garageComment', {
      name: 'garageComment',
      icon: 'far fa-comment-dots',
      label: t('notifications.comment_setting')
    });
  });

  // A build linked on a line of its own becomes its card.
  extend(CommentPost.prototype, 'oncreate', embedBuilds);
  extend(CommentPost.prototype, 'onupdate', embedBuilds);

  // With FoF Signature: the build the member chose, under their posts.
  extend(CommentPost.prototype, 'content', function (content) {
    const post = this.attrs.post;
    const card = post.user?.()?.attribute?.('garageSignature');
    if (!card || post.isHidden()) return;
    content.push(m("div", {
      className: "GarageSignature"
    }, m(EmbedCard, {
      card: card,
      compact: true
    })));
  });
});

/**
 * Swaps a paragraph's lone link to a build for the build's card. The card is
 * drawn INSIDE the paragraph (which stays where it is): Mithril tracks the
 * post's top-level nodes, and replacing one would break its next redraw.
 */
function embedBuilds() {
  const cards = this.attrs.post.attribute('garageEmbeds');
  const body = cards && this.element?.querySelector('.Post-body');
  if (!body) return;
  const base = app.forum.attribute('baseUrl') + '/garage/';
  body.querySelectorAll('a[href]:not([data-garage])').forEach(link => {
    if (!link.href.startsWith(base)) return;
    link.dataset.garage = '1';
    const match = link.href.slice(base.length).match(/^(\d+)/);
    const card = match && cards.find(c => String(c.id) === match[1]);
    const paragraph = link.parentElement;
    const alone = paragraph?.tagName === 'P' && paragraph.textContent.trim() === link.textContent.trim();
    if (!card || !alone) return;
    const holder = document.createElement('span');
    holder.className = 'GarageEmbed-holder';
    link.replaceWith(holder);
    m.render(holder, m(EmbedCard, {
      card: card
    }));
  });
}flarum.reg.addChunkModule('ernestdefoe-garage:forum/components/GaragePage', '62', 'ernestdefoe-garage', 'forum/components/GaragePage');
flarum.reg.addChunkModule('ernestdefoe-garage:forum/components/BuildPage', '853', 'ernestdefoe-garage', 'forum/components/BuildPage');
flarum.reg.addChunkModule('ernestdefoe-garage:forum/components/UserGaragePage', '577', 'ernestdefoe-garage', 'forum/components/UserGaragePage');
flarum.reg.addChunkModule('ernestdefoe-garage:forum/components/GaragePage', '62', 'ernestdefoe-garage', 'forum/components/BuildCard');
flarum.reg.addChunkModule('ernestdefoe-garage:forum/components/GaragePage', '62', 'ernestdefoe-garage', 'forum/components/openers');
flarum.reg.addChunkModule('ernestdefoe-garage:forum/components/BuildPage', '853', 'ernestdefoe-garage', 'forum/components/BuildLog');
flarum.reg.addChunkModule('ernestdefoe-garage:forum/components/BuildPage', '853', 'ernestdefoe-garage', 'forum/components/Comments');
flarum.reg.addChunkModule('ernestdefoe-garage:forum/components/BuildPage', '853', 'ernestdefoe-garage', 'forum/components/Lightbox');
flarum.reg.addChunkModule('ernestdefoe-garage:forum/components/BuildPage', '853', 'ernestdefoe-garage', 'forum/text');